var qs = new URLSearchParams(location.search);
var state = {
  lang: qs.get("lang") || localStorage.getItem("z-lang") || "ar",
  theme: qs.get("theme") || localStorage.getItem("z-theme") || (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")
};

function t(){ return T[state.lang]; }
function esc(s){ return s; }

function applyChrome(){
  var L = t();
  document.documentElement.lang = state.lang;
  document.documentElement.dir = L.dir;
  document.documentElement.setAttribute("data-theme", state.theme);
  var langBtn = document.getElementById("langToggle");
  var themeBtn = document.getElementById("themeToggle");
  if(langBtn) langBtn.textContent = L.otherLang;
  if(themeBtn) themeBtn.textContent = state.theme === "dark" ? "☀" : "☾";
}

function renderNav(){
  var page = document.body.dataset.page;
  var L = t();
  var items = [["home","index.html"],["about","about.html"],["dev","dev.html"],["design","design.html"],["certs","certificates.html"],["contact","contact.html"]];
  var html = "";
  items.forEach(function(it){
    html += '<a href="'+it[1]+'"'+(page===it[0]?' class="active"':"")+'>'+L.nav[it[0]]+'</a>';
  });
  document.getElementById("navlinks").innerHTML = html;
}

