function marqueeHTML(){
  var items = t().marquee;
  var seq = items.map(function(x){return '<span class="mitem">'+x+'</span><span class="star">✳</span>';}).join("");
  return '<div class="track"><span>'+seq+'</span><span>'+seq+'</span></div>';
}

function secHead(num,title,sub){
  return '<div class="sec-head reveal"><span class="sec-num">'+num+' /</span><h2 class="display">'+title+'</h2>'+(sub?'<p>'+sub+'</p>':"")+'</div>';
}

function pcardHTML(p,i){
  var ar = state.lang==="ar";
  var name = ar? p.nameAr : p.nameEn;
  var desc = ar? p.dAr : p.dEn;
  var L = t();
  var links = "";
  if(p.live) links += '<a href="'+p.live+'" target="_blank" rel="noopener">'+L.liveLink+' ↗</a>';
  if(p.repo) links += '<a href="'+p.repo+'" target="_blank" rel="noopener">'+L.repoLink+' ↗</a>';
  var badge = p.badge==="live" ? '<span class="badge-live">● '+L.liveBadge+'</span>' : "";
  var tags = p.tags.map(function(x){return '<span class="tag">'+x+'</span>';}).join("");
  return '<article class="pcard reveal">'+badge+
    '<span class="idx">'+String(i+1).padStart(2,"0")+'</span>'+
    (i<2?'<img class="project-shot" src="'+MEDIA[i===0?'satr':'fasli']+'" alt="'+name+'" loading="lazy">':'')+'<h3>'+name+'</h3><p>'+desc+'</p>'+
    '<div class="tags">'+tags+'</div>'+
    '<div class="plinks">'+links+'</div></article>';
}

function spinBadge(){
  return '<svg class="spin-badge" viewBox="0 0 100 100" aria-hidden="true">'+
   '<defs><path id="circ" d="M50,50 m-38,0 a38,38 0 1,1 76,0 a38,38 0 1,1 -76,0"/></defs>'+
   '<text><textPath href="#circ">CODE ✳ DESIGN ✳ ZAYNAB ✳ CODE ✳ DESIGN ✳</textPath></text></svg>'+
   '<div class="spin-core">✳</div>';
}

